use nix::unistd::fork;
use libc::execve;
use tokio::process::Command as TokioCommand;
use subprocess::Popen;

fn main() {
    // Fork and exec
    unsafe {
        let pid = fork();
    }

    // Wait for process
    child.wait();

    // libc spawn functions
    libc::posix_spawn();
    libc::system(cmd);
    libc::popen(cmd, mode);

    // Async process
    nix::unistd::daemon(false, false);
    nix::unistd::setsid();
    nix::unistd::execvp(prog, args);

    // subprocess crate
    Popen::create();
}
